<?php declare(strict_types=1);use App\Core\Database\Database;/** @var Database $db */$db=$app->make(Database::class);$tables=$db->execute("SELECT COUNT(*) total FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN('client_progress_statements','client_progress_statement_costs','client_progress_statement_variations','client_progress_statement_boq_items')")->fetch_assoc();if((int)$tables['total']!==4)throw new RuntimeException('Client progress statement tables missing.');$boqColumns=$db->execute("SELECT COUNT(*) total FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='client_progress_statements' AND COLUMN_NAME IN('previous_boq_amount','current_boq_amount','cumulative_boq_amount')")->fetch_assoc();if((int)$boqColumns['total']!==3)throw new RuntimeException('BOQ header columns missing.');$column=$db->execute("SELECT EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='client_progress_statement_costs' AND COLUMN_NAME='committed_project_actual_cost_id'")->fetch_assoc();if(!str_contains(strtolower((string)($column['EXTRA']??'')),'generated'))throw new RuntimeException('Committed cost generated column missing.');$index=$db->execute("SELECT NON_UNIQUE FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='client_progress_statement_costs' AND INDEX_NAME='uq_cps_cost_committed' LIMIT 1")->fetch_assoc();if((int)($index['NON_UNIQUE']??1)!==0)throw new RuntimeException('Committed cost uniqueness missing.');$permissions=$db->execute("SELECT COUNT(*) total FROM permissions WHERE module='client_progress_statements'")->fetch_assoc();if((int)$permissions['total']!==5)throw new RuntimeException('Client progress statement permissions missing.');$assigned=$db->execute("SELECT COUNT(*) total FROM role_permissions rp JOIN roles r ON r.id=rp.role_id JOIN permissions p ON p.id=rp.permission_id WHERE r.code='super_admin' AND p.module='client_progress_statements'")->fetch_assoc();if((int)$assigned['total']!==5)throw new RuntimeException('Client progress permissions not assigned to super_admin.');
